import { defineStore } from 'pinia'

export const usePersonFormStore = defineStore('personForm', {
  state: () => ({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    zipCode: '',
    country: '',
    notes: ''
  }),

  getters: {
    fullName: (state) => {
      if (state.firstName && state.lastName) {
        return `${state.firstName} ${state.lastName}`
      }
      return ''
    },
    isFormComplete: (state) => {
      return Boolean(state.firstName && state.lastName && state.email)
    }
  },

  actions: {
    resetForm() {
      this.$patch({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        address: '',
        city: '',
        zipCode: '',
        country: '',
        notes: ''
      })
    },

    fillDemoData() {
      this.$patch({
        firstName: 'John',
        lastName: 'Doe',
        email: 'john.doe@example.com',
        phone: '555-1234',
        address: '123 Main St',
        city: 'Anytown',
        zipCode: '12345',
        country: 'USA',
        notes: 'Demo data'
      })
    }
  }
})

